codeExamples.code:
-- Create an access role that holds READ privileges on the sales schema
USE ROLE SECURITYADMIN;
CREATE ROLE IF NOT EXISTS read_sales;
GRANT USAGE  ON DATABASE analytics             TO ROLE read_sales;
GRANT USAGE  ON SCHEMA   analytics.sales       TO ROLE read_sales;
GRANT SELECT ON ALL TABLES IN SCHEMA analytics.sales TO ROLE read_sales;
GRANT SELECT ON FUTURE TABLES IN SCHEMA analytics.sales TO ROLE read_sales; -- future-proof

-- Create a functional role and build the hierarchy (functional inherits access role)
CREATE ROLE IF NOT EXISTS analyst;
GRANT ROLE read_sales TO ROLE analyst;      -- analyst inherits read_sales privileges
GRANT ROLE analyst    TO ROLE SYSADMIN;     -- keep roles under SYSADMIN in the hierarchy

-- Assign the functional role to a user (mapped from an IdP group in practice)
GRANT ROLE analyst TO USER jdoe;

-- Verify effective privileges
SHOW GRANTS TO ROLE analyst;
SHOW GRANTS TO USER jdoe;

-- Dynamic data masking: full value for cleared roles, masked otherwise
CREATE OR REPLACE MASKING POLICY mask_pii_string AS (val STRING) RETURNS STRING ->
  CASE
    WHEN CURRENT_ROLE() IN ('COMPLIANCE','SECURITYADMIN') THEN val
    ELSE 'XXX-XX-' || RIGHT(val, 4)      -- partial mask, e.g. SSN
  END;

-- Bind the policy to a classification TAG so ALL PII-tagged columns inherit it
CREATE TAG IF NOT EXISTS pii;
ALTER TAG pii SET MASKING POLICY mask_pii_string;
-- Now tag any sensitive column; it is masked automatically
ALTER TABLE analytics.sales.customers MODIFY COLUMN ssn SET TAG pii = 'ssn';

-- Row-level security: EU roles see only EU rows
CREATE OR REPLACE ROW ACCESS POLICY rap_region AS (region STRING) RETURNS BOOLEAN ->
  CASE
    WHEN CURRENT_ROLE() = 'COMPLIANCE'  THEN TRUE                 -- sees all regions
    WHEN CURRENT_ROLE() = 'SUPPORT_EU'  THEN region = 'EU'
    WHEN CURRENT_ROLE() = 'SUPPORT_US'  THEN region = 'US'
    ELSE FALSE                                                    -- default deny
  END;
ALTER TABLE analytics.sales.customers ADD ROW ACCESS POLICY rap_region ON (region);
